function selectedMonthTransactions() {
    const selectedMonth = elements.monthFilter.value;
    return transactions.filter((transaction) => {
        const date = new Date(transaction.date);
        if (Number.isNaN(date.getTime())) return false;
        return localMonthValue(date) === selectedMonth;
    });
}

function getDaysInMonth(monthStr) {
    const [year, month] = monthStr.split('-').map(Number);
    return new Date(year, month, 0).getDate();
}

/* ================= KANTONG DANA / E-WALLET COMPACT DROPDOWN BAR ================= */
function renderWalletsSection(monthTransactions) {
    const statsByWallet = new Map();
    let totalInc = 0;
    let totalExp = 0;

    WALLET_CATALOG.forEach((w) => {
        statsByWallet.set(w.id, { meta: w, income: 0, expense: 0, count: 0 });
    });

    monthTransactions.forEach((trx) => {
        const meta = getWalletMeta(trx.wallet);
        if (!statsByWallet.has(meta.id)) {
            statsByWallet.set(meta.id, { meta, income: 0, expense: 0, count: 0 });
        }
        const entry = statsByWallet.get(meta.id);
        const amt = Number(trx.amount) || 0;
        if (trx.type === 'income') {
            entry.income += amt;
            totalInc += amt;
        } else {
            entry.expense += amt;
            totalExp += amt;
        }
        entry.count += 1;
    });

    const allWalletEntries = [...statsByWallet.values()];

    // Update select sederhana di toolbar transaksi
    const currentSelectVal = selectedWalletFilter;
    elements.walletFilterSelect.innerHTML = `<option value="all">Semua Kantong Dana</option>`;
    allWalletEntries.forEach(({ meta, count }) => {
        const opt = document.createElement('option');
        opt.value = meta.id;
        opt.textContent = `${meta.name}${count > 0 ? ` (${count})` : ''}`;
        elements.walletFilterSelect.append(opt);
    });
    elements.walletFilterSelect.value = currentSelectVal;

    // Render Trigger & Stats pada Compact Bar
    const activeMeta = getWalletMeta(selectedWalletFilter);
    const activeStats = selectedWalletFilter === 'all'
        ? { income: totalInc, expense: totalExp, count: monthTransactions.length }
        : (statsByWallet.get(activeMeta.id) || { income: 0, expense: 0, count: 0 });

    elements.activeWalletHeroLogo.innerHTML = activeMeta.logoSvg;
    elements.walletDropdownTriggerContent.innerHTML = `
        ${activeMeta.logoSvg}
        <span class="w-trig-name">${activeMeta.name}</span>
        <span class="w-trig-tag">${activeMeta.kind}</span>
    `;

    const net = activeStats.income - activeStats.expense;
    elements.selectedWalletBalance.textContent = formatCurrency(net);
    elements.selectedWalletIncome.textContent = `+${formatCurrency(activeStats.income)}`;
    elements.selectedWalletExpense.textContent = `-${formatCurrency(activeStats.expense)}`;
    elements.resetWalletFilterBtn.hidden = selectedWalletFilter === 'all';

    // Render isi menu dropdown dashboard dengan Logo Aplikasi
    elements.walletDropdownMenu.replaceChildren();

    const allOption = document.createElement('button');
    allOption.type = 'button';
    allOption.className = `wallet-opt-item${selectedWalletFilter === 'all' ? ' is-selected' : ''}`;
    allOption.innerHTML = `
        <span class="wallet-opt-left">
            ${ALL_WALLETS_LOGO_SVG}
            <span>Semua Kantong Dana</span>
        </span>
        <span class="wallet-opt-meta">${formatCurrency(totalInc - totalExp)}</span>
    `;
    allOption.addEventListener('click', () => {
        selectedWalletFilter = 'all';
        elements.walletDropdownMenu.hidden = true;
        renderDashboard();
    });
    elements.walletDropdownMenu.append(allOption);

    const groups = [
        { label: 'E-Wallet Populer', filter: (w) => w.kind === 'E-Wallet' },
        { label: 'Bank & Digital Bank', filter: (w) => w.kind.includes('Bank') },
        { label: 'Tunai & Lainnya', filter: (w) => !w.kind.includes('Bank') && w.kind !== 'E-Wallet' }
    ];

    groups.forEach((grp) => {
        const items = allWalletEntries.filter((entry) => grp.filter(entry.meta));
        if (!items.length) return;
        const lbl = document.createElement('div');
        lbl.className = 'wallet-opt-group-label';
        lbl.textContent = grp.label;
        elements.walletDropdownMenu.append(lbl);

        items.forEach(({ meta, income, expense, count }) => {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = `wallet-opt-item${selectedWalletFilter === meta.id ? ' is-selected' : ''}`;
            btn.innerHTML = `
                <span class="wallet-opt-left">
                    ${meta.logoSvg}
                    <span>${meta.name}</span>
                </span>
                <span class="wallet-opt-meta">${count > 0 ? formatCurrency(income - expense) : meta.kind}</span>
            `;
            btn.addEventListener('click', () => {
                selectedWalletFilter = meta.id;
                elements.walletDropdownMenu.hidden = true;
                renderDashboard();
            });
            elements.walletDropdownMenu.append(btn);
        });
    });

    // Render isi menu dropdown pada Form Modal Transaksi
    renderFormWalletDropdownMenu();
}

